program = r'''from collections import Counter, deque

def transform(grid):
    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])
    coords5 = [(r,c) for r in range(H) for c in range(W) if g[r][c] == 5]
    r0, r1 = min(r for r,c in coords5), max(r for r,c in coords5)
    c0, c1 = min(c for r,c in coords5), max(c for r,c in coords5)
    bg = Counter(g[r][c] for r in range(H) for c in range(W) if not (r0 <= r <= r1 and c0 <= c <= c1)).most_common(1)[0][0]

    def components(region, rbase=0, cbase=0, exclude=()):
        h, w = len(region), len(region[0])
        seen, ans = set(), []
        for r in range(h):
            for c in range(w):
                color = region[r][c]
                if color == bg or color in exclude or (r,c) in seen: continue
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    a,b=q.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and (x,y) not in seen and region[x][y]==color:
                            seen.add((x,y)); q.append((x,y))
                rs=[x for x,y in cells]; cs=[y for x,y in cells]
                ans.append({'color':color,'cells':cells,'box':(min(rs)+rbase,min(cs)+cbase,max(rs)+rbase,max(cs)+cbase)})
        return ans

    outside = [row[:c0]+row[c1+1:] for row in g[:r0]] + [row[:c0]+row[c1+1:] for row in g[r1+1:]]
    # Work on the whole grid, ignoring the framed region.
    masked = [[bg if r0<=r<=r1 and c0<=c<=c1 else g[r][c] for c in range(W)] for r in range(H)]
    objs = components(masked)
    small = [o for o in objs if o['box'][2]-o['box'][0]+1 == 3 and o['box'][3]-o['box'][1]+1 <= 4]
    mapping = {}
    for a in small:
        ar,ac,_,_ = a['box']
        acells={(r-ar,c-ac) for r,c in a['cells']}
        candidates=[]
        for b in small:
            if b is a: continue
            br,bc,_,_=b['box']
            bcells={(r-br,c-bc) for r,c in b['cells']}
            if br==ar and acells==bcells: candidates.append(b)
        if candidates:
            b=min(candidates,key=lambda o:abs(o['box'][1]-ac))
            mapping[a['color']]=b['color']
    for o in small:
        if o['color'] not in mapping and any(o['color']==x['color'] for x in components([row[c0:c1+1] for row in g[r0:r1+1]],exclude=(5,))):
            mapping[o['color']]=4

    patterns={}
    for o in objs:
        if o in small: continue
        a,b,c,d=o['box']; h,w=c-a+1,d-b+1
        patterns[o['color']]=[[masked[a+i][b+j]!=bg for j in range(w)] for i in range(h)]

    crop=[row[c0:c1+1] for row in g[r0:r1+1]]
    inside=components(crop,exclude=(5,))
    for o in inside:
        a,b,c,d=o['box']; color=o['color']; new=mapping.get(color,color)
        pat=patterns.get(color)
        for r,cc in o['cells']:
            crop[r][cc]=new
            if pat and 0<=r-a<len(pat) and 0<=cc-b<len(pat[0]) and not pat[r-a][cc-b]:
                crop[r][cc]=bg
    return crop
'''
